import { Component, input } from '@angular/core';
import { FigurePipe } from '../../core/figure.pipe';
import { StatusSummary } from './summary';

// The sheet's counters, shown at all times: everyone on it (retired people included), the claims in
// each status as the summary counts them, the sheet's due-total and overdue-total, and
// the signed-in user's own when a person on the sheet has their name or alias.
@Component({
  selector: 'app-sheet-header',
  imports: [FigurePipe],
  template: `
    <section aria-label="Sheet counters" data-testid="sheet-header">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() }}</dd>
        @for (s of statuses(); track s.status) {
          <dt>{{ s.status }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd>
        }
        <dt>Due</dt>
        <dd data-testid="header-due-total">{{ dueTotal() | figure }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() | figure }}</dd>
        <dt>My due</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() | figure }}</dd>
        <dt>My overdue</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() | figure }}</dd>
      </dl>
    </section>
  `,
})
export class SheetHeader {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
  /** The signed-in user's own due-total and overdue-total; blank when no one on the sheet has their name. */
  readonly myDueTotal = input.required<string>();
  readonly myOverdueTotal = input.required<string>();
}
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface CrewView {
  id: number;
  name: string;
  /** The lead, a person of the sheet. */
  leadId: number;
  /** The members' person ids in the order they were added. */
  memberIds: number[];
}

// The crews of a sheet, as the store holds them.
@Injectable({ providedIn: 'root' })
export class CrewsApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/crews`;
  }

  /** The sheet's crews in the order they were added. */
  list(sheetId: string): Promise<CrewView[]> {
    return firstValueFrom(this.http.get<CrewView[]>(this.url(sheetId)));
  }

  /** Add a crew with a lead: refused for a blank name or one the sheet already has. */
  add(sheetId: string, name: string, leadId: number): Promise<CrewView> {
    return firstValueFrom(this.http.post<CrewView>(this.url(sheetId), { name, leadId }));
  }

  /** Add a person to a crew's members: refused for its lead or a member already. The crew as it is then. */
  addMember(sheetId: string, crewId: number, personId: number): Promise<CrewView> {
    return firstValueFrom(this.http.post<CrewView>(`${this.url(sheetId)}/${crewId}/members`, { personId }));
  }
}

// The active sheet's crews. Each load of a sheet re-reads them from the store.
@Injectable({ providedIn: 'root' })
export class Crews {
  private readonly session = inject(Session);
  private readonly api = inject(CrewsApi);

  private readonly state = signal<CrewView[]>([]);
  readonly crews = this.state.asReadonly();
  /** The refusal of the last loading of the crews, or blank. */
  readonly loadError = signal('');

  constructor() {
    effect(() => {
      const sheet = this.session.loaded();
      this.state.set([]);
      this.loadError.set('');
      if (sheet) void this.load(sheet.id);
    });
  }

  private async load(sheetId: string): Promise<void> {
    try {
      const list = await this.session.reading(this.api.list(sheetId));
      if (this.session.sheet()?.id === sheetId) this.state.set(list);
    } catch {
      if (this.session.sheet()?.id === sheetId) this.loadError.set('The crews could not be loaded.');
    }
  }

  /** Re-read the sheet's crews from the store, as after a change that moves their people. */
  refresh(sheetId: string): Promise<void> {
    return this.load(sheetId);
  }

  /** Add a crew to the active sheet. */
  async add(sheetId: string, name: string, leadId: number): Promise<void> {
    const added = await this.api.add(sheetId, name, leadId);
    if (this.session.sheet()?.id !== sheetId) return;
    this.state.update((list) => [...list.filter((c) => c.id !== added.id), added]);
  }

  /** Add a member to a crew of the active sheet; the store's answer replaces the crew. */
  async addMember(sheetId: string, crewId: number, personId: number): Promise<void> {
    const crew = await this.api.addMember(sheetId, crewId, personId);
    if (this.session.sheet()?.id !== sheetId) return;
    this.state.update((list) => list.map((c) => (c.id === crew.id ? crew : c)));
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { FigurePipe } from '../../core/figure.pipe';
import { Session } from '../../core/session';
import { money } from '../claims/claims-api';
import { PersonView } from '../people/people-api';
import { CrewView, Crews } from './crews-api';

// One crew: its lead, its members, its due-total (the lead's and the members' due-totals added up, n/a
// skipped) and a form to add a member.
@Component({
  selector: 'app-crew-row',
  imports: [FigurePipe, ReactiveFormsModule],
  host: { '[attr.data-testid]': "'crew-row-' + crew().name", role: 'listitem' },
  template: `
    <h3 data-testid="crew-name">{{ crew().name }}</h3>
    <p>
      Lead <span data-testid="crew-lead">{{ nameOf(crew().leadId) }}</span>,
      due-total <span data-testid="crew-due-total">{{ dueTotal() | figure }}</span>
    </p>
    <ul [attr.aria-label]="'Members of ' + crew().name">
      @for (id of crew().memberIds; track id) {
        <li data-testid="crew-member-line">{{ nameOf(id) }}</li>
      }
    </ul>
    <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="'Add a member to ' + crew().name">
      <label [for]="'crew-member-select-' + crew().id">Person</label>
      <select [id]="'crew-member-select-' + crew().id" data-testid="crew-member-select" formControlName="personId">
        <option value="">Choose a person</option>
        @for (p of people(); track p.id) {
          <option [value]="'' + p.id">{{ p.name }}</option>
        }
      </select>
      <button type="submit" data-testid="crew-member-add" [disabled]="saving()">Add member</button>
      @if (error()) {
        <p role="alert" data-testid="crew-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class CrewRow {
  private readonly session = inject(Session);
  private readonly store = inject(Crews);

  readonly crew = input.required<CrewView>();
  /** Everyone on the sheet, retired or not. */
  readonly people = input.required<PersonView[]>();
  /** Each person's due-total in cents, by person id; null when it is n/a. */
  readonly dues = input.required<ReadonlyMap<number, number | null>>();

  private readonly namesById = computed(() => new Map(this.people().map((p) => [p.id, p.name])));
  protected readonly dueTotal = computed(() => {
    const crew = this.crew();
    return money([crew.leadId, ...crew.memberIds].reduce((t, id) => t + (this.dues().get(id) ?? 0), 0));
  });

  protected readonly personId = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ personId: this.personId });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected nameOf(id: number): string {
    return this.namesById().get(id) ?? '';
  }

  protected async submit(): Promise<void> {
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    const crew = this.crew();
    const personId = Number(this.personId.value);
    if (this.personId.value === '' || !Number.isInteger(personId)) {
      this.error.set('Choose a person.');
      return;
    }
    if (crew.leadId === personId) {
      this.error.set(`${this.nameOf(personId)} leads the crew ${crew.name}.`);
      return;
    }
    if (crew.memberIds.includes(personId)) {
      this.error.set(`${this.nameOf(personId)} is already in the crew ${crew.name}.`);
      return;
    }
    this.saving.set(true);
    try {
      await this.store.addMember(sheet.id, crew.id, personId);
      if (this.session.sheet()?.id === sheet.id) this.form.reset({ personId: '' }, { emitEvent: false });
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.error.set(status === 403 ? 'Your role may not change a crew on this sheet.'
        : status === 409 ? 'That person is the lead or already in the crew.'
        : status === 422 ? 'Choose a person of the sheet.'
        : 'The member could not be added.');
    } finally {
      this.saving.set(false);
    }
  }
}

// The sheet's crews, with a form to add one.
@Component({
  selector: 'app-crews',
  imports: [ReactiveFormsModule, CrewRow],
  template: `
    <section aria-labelledby="crews-heading">
      <h2 id="crews-heading">Crews</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Add a crew">
        <label for="crew-form-name">Name</label>
        <input id="crew-form-name" data-testid="crew-form-name" formControlName="name" />
        <label for="crew-form-lead">Lead</label>
        <select id="crew-form-lead" data-testid="crew-form-lead" formControlName="leadId">
          <option value="">Choose a lead</option>
          @for (p of people(); track p.id) {
            <option [value]="'' + p.id">{{ p.name }}</option>
          }
        </select>
        <button type="submit" data-testid="crew-form-submit" [disabled]="saving()">Add crew</button>
        @if (error() || store.loadError(); as message) {
          <p role="alert" data-testid="crew-form-error">{{ message }}</p>
        }
      </form>
      <div role="list" aria-label="Crews">
        @for (c of store.crews(); track c.id) {
          <app-crew-row [crew]="c" [people]="people()" [dues]="dues()" />
        }
      </div>
    </section>
  `,
})
export class CrewsList {
  private readonly session = inject(Session);
  protected readonly store = inject(Crews);

  /** Everyone on the sheet, retired or not. */
  readonly people = input.required<PersonView[]>();
  /** Each person's due-total in cents, by person id; null when it is n/a. */
  readonly dues = input.required<ReadonlyMap<number, number | null>>();

  protected readonly name = new FormControl('', { nonNullable: true });
  protected readonly leadId = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ name: this.name, leadId: this.leadId });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected async submit(): Promise<void> {
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    const name = this.name.value.trim();
    const leadId = Number(this.leadId.value);
    if (name === '') {
      this.error.set('Type a crew name.');
      return;
    }
    if (this.store.crews().some((c) => c.name === name)) {
      this.error.set(`The sheet already has a crew "${name}".`);
      return;
    }
    if (this.leadId.value === '' || !Number.isInteger(leadId)) {
      this.error.set('Choose a lead.');
      return;
    }
    this.saving.set(true);
    try {
      await this.store.add(sheet.id, name, leadId);
      if (this.session.sheet()?.id === sheet.id) this.form.reset({ name: '', leadId: '' }, { emitEvent: false });
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.error.set(status === 403 ? 'Your role may not add a crew on this sheet.'
        : status === 409 ? `The sheet already has a crew "${name}".`
        : status === 422 ? 'Type a crew name and choose a lead.'
        : 'The crew could not be added.');
    } finally {
      this.saving.set(false);
    }
  }
}
